import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Keynote- Powered by People- Growing the Ceph Community Through User Engagement - Anthony Middleton","description":"","frontmatter":{"title":"Keynote- Powered by People- Growing the Ceph Community Through User Engagement - Anthony Middleton","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph社区","用户参与","开源技术","分布式存储","Ceph Days"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_Powered_by_People_-_Growing_the_Ceph_Community_Through_User_Engagement_-_Anthony_Middleton.md","filePath":"posts/2025/Keynote_-_Powered_by_People_-_Growing_the_Ceph_Community_Through_User_Engagement_-_Anthony_Middleton.md","lastUpdated":1780459816000}'),l={name:"posts/2025/Keynote_-_Powered_by_People_-_Growing_the_Ceph_Community_Through_User_Engagement_-_Anthony_Middleton.md"};function i(r,e,h,_,d,s){return t(),o("div",null,[...e[0]||(e[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议基本信息</strong></p><ul><li><strong>主讲人</strong>：Anthony Middleton（Ceph社区经理）</li><li><strong>会议地点</strong>：Cephalocon（温哥华）</li><li><strong>会议主题</strong>：通过用户参与推动Ceph社区发展</li></ul><p><strong>关键内容总结</strong></p><h4 id="_1-主讲人介绍" tabindex="-1">1. 主讲人介绍 <a class="header-anchor" href="#_1-主讲人介绍" aria-label="Permalink to &quot;1. 主讲人介绍&quot;">​</a></h4><p>Anthony Middleton是Ceph社区经理，拥有7年技术社区运营经验，专注于开源技术推广。</p><h4 id="_2-ceph社区现状与成果" tabindex="-1">2. Ceph社区现状与成果 <a class="header-anchor" href="#_2-ceph社区现状与成果" aria-label="Permalink to &quot;2. Ceph社区现状与成果&quot;">​</a></h4><p>自2023年5月以来，Ceph社区发布了12+篇博客文章，LinkedIn粉丝增长700+，并加强了SEF Governing Board与社区的透明度。</p><h4 id="_3-2026年社区发展计划" tabindex="-1">3. 2026年社区发展计划 <a class="header-anchor" href="#_3-2026年社区发展计划" aria-label="Permalink to &quot;3. 2026年社区发展计划&quot;">​</a></h4><ul><li>扩展Ceph Days活动，在亚洲和北美举办更多活动。</li><li>使用数据追踪工具评估社区健康度与参与度。</li><li>推出贡献者认可计划，包括代码开发者、文档贡献者、技术演讲者、社区倡导者。</li><li>定期同步Governing Board动态。</li></ul><h4 id="_4-ceph用户的核心价值" tabindex="-1">4. Ceph用户的核心价值 <a class="header-anchor" href="#_4-ceph用户的核心价值" aria-label="Permalink to &quot;4. Ceph用户的核心价值&quot;">​</a></h4><p>Ceph用户是社区的核心，他们首先发现问题、分享反馈并推动创新。</p><h4 id="_5-如何参与社区" tabindex="-1">5. 如何参与社区？ <a class="header-anchor" href="#_5-如何参与社区" aria-label="Permalink to &quot;5. 如何参与社区？&quot;">​</a></h4><ul><li>撰写技术博客。</li><li>重启月度Technical Talks。</li><li>参与.Ceph Days。</li><li>通过Slack、LinkedIn、Twitter等平台互动。</li><li>完成社区调研。</li></ul><h4 id="_6-新工具提案-社区贡献者数据库" tabindex="-1">6. 新工具提案：社区贡献者数据库 <a class="header-anchor" href="#_6-新工具提案-社区贡献者数据库" aria-label="Permalink to &quot;6. 新工具提案：社区贡献者数据库&quot;">​</a></h4><p>建立社区成员技能与兴趣的数据库，快速匹配任务需求。</p><h4 id="行动计划与下一步" tabindex="-1">行动计划与下一步 <a class="header-anchor" href="#行动计划与下一步" aria-label="Permalink to &quot;行动计划与下一步&quot;">​</a></h4><ul><li>短期（2023年底前）：启动Technical Talks月度会议。</li><li>中期（2024年）：落实亚洲/北美Ceph Days。</li><li>长期（2026年）：优化社区反馈闭环。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>联系方式：Anthony Middleton（邮件/Slack/LinkedIn）。</li><li>社区福利：现场发放Ceph主题贴纸。</li></ul><p><strong>会议结束</strong>：掌声致谢，鼓励参与者继续支持Ceph开源生态。</p>',21)])])}const c=a(l,[["render",i]]);export{u as __pageData,c as default};
